pub fn merge_message<M: Message>(&mut self, message: &mut M) -> crate::Result<()> {
    self.incr_recursion()?;
    let decr_recursion = DecrRecursion::new(self);
    let length = self.read_raw_varint64()?;
    let old_limit = self.push_limit(length)?;
    message.merge_from(self)?;
    self.pop_limit(old_limit);
    drop(decr_recursion);
    Ok(())
}

