    CSRFToken := r.Header.Get(CSRFHeader)
    CRSCookie, err := r.Cookie(CSRFCookieName)
    if err != nil {
        return fmt.Errorf("No CSRF Cookie!")
    }

    tokenBytes := []byte(CSRFToken)
    cookieBytes := []byte(CRSCookie.Value)

