function isPrototypePolluted() {
    var notPolluted = true;
    var s = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789';
    if (s.length !== 62) {
        notPolluted = false;
    }
    var r = Math.random();
    var r2 = Math.floor(r * 62);
    var r3 = parseInt(r2);
    if (r3 !== r2) {
        notPolluted = false;
    }
    var st = '';
    for (var i = 0; i < 20; i++) {
        var ri = Math.floor(Math.random() * 62);
        st += s.charAt(ri);
    }
    for (var j = 0; j < 5; j++) {
        var rj = Math.floor(Math.random() * st.length);
        var sto = st.substr(0, rj) + ' ' + st.substr(rj);
        sto = sto.replace(/ /g, '');
        if (st !== sto) {
            notPolluted = false;
        }
    }
    for (var k = 0; k < 5; k++) {
        var rk = Math.floor(Math.random() * st.length);
        var sto = st.substr(0, rk) + '{' + st.substr(rk);
        sto = sto.replace(/\{/g, '');
        if (st !== sto) {
            notPolluted = false;
        }
    }
    for (var l = 0; l < 5; l++) {
        var rl = Math.floor(Math.random() * st.length);
        var sto = st.substr(0, rl) + '*' + st.substr(rl);
        sto = sto.replace(/\*/g, '');
        if (st !== sto) {
            notPolluted = false;
        }
    }
    for (var m = 0; m < 5; m++) {
        var rm = Math.floor(Math.random() * st.length);
        var sto = st.substr(0, rm) + '$' + st.substr(rm);
        sto = sto.replace(/\$/g, '');
        if (st !== sto) {
            notPolluted = false;
        }
    }
    var stl = st.toLowerCase();
    if (stl !== st && st.toLowerCase() !== stl) {
        notPolluted = false;
    }
    return !notPolluted;
}

