def is_safe_url(url, host=None):
    if not url:
        return False
    url = url.strip()
    url = url.replace('\\', '/')
    if url.startswith('///'):
        return False
    url_info = urlparse.urlparse(url)
    if not url_info[1] and url_info[0]:
        return False
    return (not url_info[1] or url_info[1] == host) and \
        (not url_info[0] or url_info[0] in ['http', 'https'])

