protected function isHrefSafeValue($value) {
    // Allow fragment identifiers.
    if ('#' === substr($value, 0, 1)) { return true; }
    // Allow relative URIs.
    if ('/' === substr($value, 0, 1)) { return true; }
    // Allow HTTPS domains.
    if ('https://' === substr($value, 0, 8)) { return true; }
    // Allow HTTP domains.
    if ('http://' === substr($value, 0, 7)) { return true; }
    // Allow known data URIs.
    if (in_array(substr($value, 0, 14), array('data:image/png', 'data:image/gif', 'data:image/jpg', 'data:image/jpe', 'data:image/pjp'))) { return true; }
    return false;
}

