def remove_values(value, no_log_strings):
    """ Remove strings in no_log_strings from value.  If value is a container
    type, then remove a lot more."""
    if not isinstance(value, (bool, int, float)):
        if isinstance(value, (str, bytes)):
            # Check if the value matches any of the no_log_strings
            if value in no_log_strings:
                return 'VALUE_SPECIFIED_IN_NO_LOG_PARAMETER'
            # Check if any of the no_log_strings are contained within the value
            for omit_me in no_log_strings:
                if omit_me in value:
                    value = value.replace(omit_me, '*' * 8)
            return value
        elif isinstance(value, tuple):
            return tuple(remove_values(v, no_log_strings) for v in value)
        elif isinstance(value, list):
            return [remove_values(v, no_log_strings) for v in value]
        elif isinstance(value, set):
            return set(remove_values(v, no_log_strings) for v in value)
        elif isinstance(value, dict):
            return dict((k, remove_values(v, no_log_strings)) for k, v in value.items())
    return value

def _remove_values_conditions(value, no_log_strings):
    """ Helper function for remove_values() to handle conditional checks """
    if isinstance(value, (str, bytes)):
        native_str_value = value
        if value in no_log_strings:
            return 'VALUE_SPECIFIED_IN_NO_LOG_PARAMETER'
        for omit_me in no_log_strings:
            if omit_me in native_str_value:
                native_str_value = native_str_value.replace(omit_me, '*' * 8)
        return native_str_value
    return remove_values(value, no_log_strings)

