public class HeaderValueConverterAndValidator implements Converter<String, String> {

    @Override
    public String convertObject(String source) {
        if (source == null) {
            return null;
        }
        char[] chars = source.toCharArray();
        int state = 0;
        for (char c : chars) {
            validateValueChar(c, state);
            switch (c) {
                case '\r':
                    state = 1;
                    break;
                case '\n':
                    if (state != 1) {
                        throw new IllegalArgumentException("Unexpected LF without CR");
                    }
                    state = 2;
                    break;
                case '\t':
                case ' ':
                    if (state == 2) {
                        state = 0;
                    }
                    break;
                default:
                    if (state == 2) {
                        throw new IllegalArgumentException("Invalid character after CRLF sequence");
                    }
                    state = 0;
                    break;
            }
        }
        if (state != 0) {
            throw new IllegalArgumentException("Unterminated CRLF sequence");
        }
        return source;
    }

    private void validateValueChar(char c, int state) {
        if (c == '\0' || c == '\f' || c == '\u000b') { // VT vertical tab
            throw new IllegalArgumentException("Invalid character in header value: " + (int) c);
        }
    }
}

